import timedef validar_movimientos(pos_inicial, cadena_movimientos):    # Convertir posición a coordenadas    col_inicial = ord(pos_inicial[0]) - ord('a') + 1    fila_inicial = int(pos_inicial[1])        actual_fila = fila_inicial    actual_col = col_inicial        movimientos = cadena_movimientos.split()        # Evaluamos todos los movimientos que haya en la cadena    for i, mov in enumerate(movimientos):        if mov[0] != 'K':            return f"INCORRECTO falla letra {mov[0]} no pertenece a un caballo."                    destino_col = ord(mov[1]) - ord('a') + 1        destino_fila = int(mov[2])                df = abs(destino_fila - actual_fila)        dc = abs(destino_col - actual_col)                if not ((df == 1 and dc == 2) or (df == 2 and dc == 1)):            return f"INCORRECTO falla en el movimiento {i+1}"                    actual_fila = destino_fila        actual_col = destino_col            return f"CORRECTO ({len(movimientos)} movimientos validados)"# --- CADENA EXACTA DEL PDF (245 movimientos) ---cadena_pdf = """Kb4 Ka6 Kc5 Ka4 Kc3 Ka2 Kc1 Ke2 Kg1 Kh3 Kg5 Ke6 Kc7 Ka8 Kc7 Kb5 Kd6 Kb7 Ka5 Kc4 Ka3 Kc2 Ka1 Kc2 Kb4 Ka6 Kb8 Kd7 Kb6 Ka8 Kc7 Ka6 Kc5 Ka4 Kc3 Ka2 Kc1 Ke2 Kg3 Kh5 Kg7 Ke8 Kc7 Ka8 Kc7 Kb5 Kd4 Kb3 Ka1 Kc2 Ka3 Kc4 Ka5 Kc6 Ka7 Kc8 Ka7 Kc6 Ka5 Kc4 Ka3 Kc2 Ka1 Kc2 Kb4 Kd5 Kb6 Ka8 Kc7 Ka6 Kc5 Ka4 Kc3 Ka2 Kc1 Ke2 Kg1 Kh3 Kg5 Ke6 Kc5 Ka4 Kc3 Ka2 Kc1 Ke2 Kg3 Kh5 Kg7 Ke8 Kc7 Ka8 Kc7 Kb5 Kd6 Kb7 Ka5 Kc4 Ka3 Kc2 Ka1 Kc2 Kb4 Kb6 Kd7 Kb6 Ka8 Kc7 Ka6 Kc5 Ka4 Kc3 Ka2 Kc1 Ke2 Kg3 Kh5 Kg7 Ke8 Kc7 Ka8 Kc7 Kb5 Kd4 Kb3 Ka1 Kc2 Ka3 Kc4 Ka5 Kc6 Ka7 Kc8 Ka7 Kc6 Ka5 Kc4 Ka3 Kc2 Ka1 Kc2 Kb4 Kd5 Kb6 Ka8 Kc7 Ka6 Kc5 Ka4 Kc3 Ka2 Kc1 Ke2 Kg1 Kh3 Kg5 Ke6 Kc5 Ka4 Kc3 Ka2 Kc1 Ke2 Kg3 Kh5 Kg7 Ke8 Kc7 Ka8 Kc7 Kb5 Kd4 Kb3 Ka1 Kc2 Ka3 Kc4 Ka5 Kc6 Ka7 Kc8 Ka7 Kc6 Ka5 Kc4 Ka3 Kc2 Ka1 Kc2 Kb4 Kb6 Kb8 Kd7 Kb6 Ka8 Kc7 Ka6 Kc5 Ka4 Kc3 Ka2 Kc1 Ke2 Kg3 Kh5 Kg7 Ke8 Kc7 Ka8 Kc7 Kb5 Kd4 Kb3 Ka1 Kc2 Ka3 Kc4 Ka5 Kc6 Ka7 Kc8 Ka7 Kc6 Ka5 Kc4 Ka3 Kc2 Ka1 Kc2 Kb4 Kb6 Ka8"""# --- MEDICIÓN DE TIEMPOS ---# 1. Tiempo para n=100lista_movs = cadena_pdf.split()primeros_100 = " ".join(lista_movs[:100])inicio_n100 = time.perf_counter()res_n100 = validar_movimientos("c2", primeros_100)fin_n100 = time.perf_counter()print("--- TIEMPO PARA N=100 ---")print(f"Resultado: {res_n100}")print(f"Tiempo n=100: {(fin_n100 - inicio_n100) * 1000:.6f} milisegundos\n")# 2. Tiempo para la cadena completa del PDF, repetida 10 vecesinicio_500 = time.perf_counter()for _ in range(10):    res_full = validar_movimientos("c2", cadena_pdf)fin_500 = time.perf_counter()print("--- TIEMPO 10 VECES LA CADENA DEL PDF ---")print(f"Resultado de la cadena original: {res_full}")print(f"Tiempo total (10 ejecuciones): {(fin_500 - inicio_500) * 1000:.6f} milisegundos")print(f"Tiempo promedio por ejecución: {((fin_500 - inicio_500) * 1000) / 10:.6f} milisegundos")